INSERT INTO public.academy_facultades (id, nombre, orden) VALUES ('3c452d30-71e2-45aa-88f8-0b5b24032bfd', 'Facultad de Liderazgo', 1);
INSERT INTO public.academy_diplomados (id, facultad_id, numero, titulo, subtitulo, duracion, modalidad, nivel, objetivo_general, dirigido_a, competencias, proyecto_final, orden) VALUES ('90eaa718-ecaf-499c-bf89-0ae81cd915dd', '3c452d30-71e2-45aa-88f8-0b5b24032bfd', 'III', 'Liderazgo Ministerial', NULL, '40 Horas', 'Presencial • Virtual • Híbrida', 'Diplomado Profesional', 'Desarrollar líderes íntegros, estratégicos y multiplicadores, capaces de inspirar, formar equipos, administrar ministerios y desarrollar nuevos líderes que contribuyan al cumplimiento de la visión de la iglesia.', '["Pastores","Copastores","Líderes de ministerio","Líderes de Casas de Paz","Coordinadores","Supervisores","Aspirantes al liderazgo"]'::jsonb, '["Comprender el liderazgo bíblico y contemporáneo","Desarrollar un carácter íntegro","Liderar equipos de alto desempeño","Comunicar con influencia","Resolver conflictos de manera saludable","Formar y acompañar nuevos líderes","Dirigir reuniones efectivas","Tomar decisiones estratégicas","Gestionar el cambio","Construir un plan de desarrollo para líderes"]'::jsonb, '["Diagnóstico del liderazgo de la iglesia","Perfil de competencias para líderes","Ruta de formación y mentoría","Sistema de evaluación","Plan de sucesión","Estrategia de multiplicación de líderes","Indicadores de crecimiento","Cronograma anual de implementación"]'::jsonb, 1);
INSERT INTO public.academy_modulos (id, diplomado_id, nombre, objetivo, temas, taller, orden) VALUES ('a63797ac-15c8-4bc9-9f5c-2fa19410bf2e', '90eaa718-ecaf-499c-bf89-0ae81cd915dd', 'Fundamentos del Liderazgo Ministerial', 'Comprender los principios fundamentales del liderazgo cristiano y su impacto en el desarrollo de la iglesia.', '["¿Qué es el liderazgo?","Liderazgo y servicio","Liderazgo bíblico","El llamado al liderazgo","Liderazgo e influencia","Autoridad y responsabilidad","Modelos de liderazgo","Liderazgo transformacional","El líder como ejemplo","Tendencias del siglo XXI"]'::jsonb, 'Diagnóstico del estilo personal de liderazgo.', 1);
INSERT INTO public.academy_modulos (id, diplomado_id, nombre, objetivo, temas, taller, orden) VALUES ('3f5f2108-a381-4459-8a2a-6301fcc2048f', '90eaa718-ecaf-499c-bf89-0ae81cd915dd', 'Carácter e Integridad del Líder', 'Fortalecer el carácter como fundamento del liderazgo ministerial.', '["El carácter del líder","Integridad","Ética ministerial","Humildad y servicio","Credibilidad","Disciplina personal","Administración del tiempo","Vida espiritual del líder","Manejo del éxito y del fracaso"]'::jsonb, 'Plan personal de crecimiento.', 2);
INSERT INTO public.academy_modulos (id, diplomado_id, nombre, objetivo, temas, taller, orden) VALUES ('50bd77b1-c162-40ea-a135-704359feb052', '90eaa718-ecaf-499c-bf89-0ae81cd915dd', 'Inteligencia Emocional', 'Desarrollar habilidades emocionales para liderar personas de manera efectiva.', '["Inteligencia emocional","Autoconocimiento","Autocontrol","Motivación","Empatía","Relaciones interpersonales","Manejo del estrés","Liderazgo emocional","Salud emocional"]'::jsonb, 'Evaluación del perfil emocional.', 3);
INSERT INTO public.academy_modulos (id, diplomado_id, nombre, objetivo, temas, taller, orden) VALUES ('9f9b939e-458c-4a25-a201-6fb405fa8565', '90eaa718-ecaf-499c-bf89-0ae81cd915dd', 'Comunicación de Alto Impacto', 'Desarrollar habilidades de comunicación para influir, enseñar y liderar.', '["Comunicación efectiva","Comunicación verbal y no verbal","Escucha activa","Retroalimentación","Comunicación en equipos","Hablar en público","Presentaciones efectivas","Storytelling","Comunicación digital"]'::jsonb, 'Presentación de una enseñanza de 10 minutos.', 4);
INSERT INTO public.academy_modulos (id, diplomado_id, nombre, objetivo, temas, taller, orden) VALUES ('e5766bfb-b8b8-4412-b427-a95c832b64dd', '90eaa718-ecaf-499c-bf89-0ae81cd915dd', 'Liderazgo de Equipos', 'Aprender a formar, desarrollar y fortalecer equipos ministeriales.', '["Equipos de alto desempeño","Roles en el equipo","Diversidad de dones","Delegación","Empoderamiento","Motivación","Cultura de colaboración","Seguimiento y evaluación del desempeño"]'::jsonb, 'Diseño del plan de fortalecimiento de un ministerio.', 5);
