INSERT INTO public.academy_modulos (id, diplomado_id, nombre, objetivo, temas, taller, orden) VALUES ('c10560a7-48c8-4467-84f5-0010797da340', '90eaa718-ecaf-499c-bf89-0ae81cd915dd', 'Proyecto Integrador', 'Integrar los conocimientos adquiridos mediante el diseño de un plan de liderazgo para la iglesia.', '["Diagnóstico del liderazgo actual","Definición del perfil de líder","Ruta de formación","Sistema de mentoría","Evaluación de líderes","Indicadores de desarrollo","Plan de sucesión","Cronograma de implementación","Presentación del proyecto"]'::jsonb, NULL, 10);
