INSERT INTO public.academy_modulos (id, diplomado_id, nombre, objetivo, temas, taller, orden) VALUES ('5c42ea08-cd85-4912-a487-a9ee15cf5997', 'bb598d5b-3a6d-475e-8645-d6dd4399c4e7', 'Diagnóstico Organizacional', 'Analizar la situación actual de la iglesia para identificar oportunidades de mejora.', '["Diagnóstico institucional","Análisis interno y externo","Análisis FODA","Identificación de oportunidades","Riesgos organizacionales","Factores críticos de éxito","Priorización de problemas","Elaboración del diagnóstico"]'::jsonb, 'Construcción del FODA institucional.', 2);
