INSERT INTO public.academy_modulos (id, diplomado_id, nombre, objetivo, temas, taller, orden) VALUES ('ad05ddf4-e633-4559-973c-3d50f99e4e96', 'bb598d5b-3a6d-475e-8645-d6dd4399c4e7', 'Toma de Decisiones Basada en Datos', 'Desarrollar una cultura organizacional orientada al análisis de información.', '["Datos vs opiniones","Análisis de información","Interpretación de indicadores","Reuniones estratégicas","Gestión del conocimiento","Resolución de problemas","Priorización","Herramientas de análisis"]'::jsonb, 'Análisis de un tablero de indicadores.', 8);
