INSERT INTO public.academy_modulos (id, diplomado_id, nombre, objetivo, temas, taller, orden) VALUES ('fef50491-f1e0-4b28-aacb-778eab1f1194', 'bb598d5b-3a6d-475e-8645-d6dd4399c4e7', 'Diseño del Plan Estratégico Institucional', 'Integrar todo lo aprendido en un plan estratégico listo para implementar.', '["Consolidación del diagnóstico","Formulación de objetivos","Definición de indicadores","Diseño del mapa estratégico","Plan operativo anual","Cronograma institucional","Asignación de responsables","Seguimiento y evaluación","Presentación ejecutiva"]'::jsonb, NULL, 10);
