INSERT INTO public.academy_diplomados (id, facultad_id, numero, titulo, subtitulo, duracion, modalidad, nivel, objetivo_general, dirigido_a, competencias, proyecto_final, orden) VALUES ('1f087b6a-3dd1-415b-ba30-b86c2382d65d', '83bfcf89-6ba5-41bf-9ab8-7cd3bcfb0e3a', 'I', 'Visión y Cultura Organizacional', NULL, '40 Horas (10 módulos de 4 horas)', 'Presencial • Virtual • Híbrida', 'Diplomado Profesional', 'Fortalecer la identidad, la visión y la cultura organizacional de la iglesia para alinear el liderazgo, los ministerios, los procesos y las personas con el propósito que Dios ha establecido, promoviendo una cultura saludable que impulse el crecimiento, la unidad y el cumplimiento de la misión.', '[]'::jsonb, '["Comprender los fundamentos de la visión organizacional","Definir y fortalecer la identidad institucional","Construir una cultura organizacional saludable","Comunicar eficazmente la visión","Desarrollar líderes que modelen la cultura","Gestionar procesos de cambio","Diseñar estructuras organizacionales alineadas con la visión","Desarrollar equipos comprometidos","Medir la cultura mediante indicadores","Diseñar un Plan Estratégico de Cultura Organizacional"]'::jsonb, '["Diagnóstico de la cultura organizacional","Declaración de visión, misión y valores","Definición del ADN institucional","Estrategia de comunicación de la visión","Plan de fortalecimiento del liderazgo","Modelo de gobierno organizacional","Plan de desarrollo de equipos","Sistema de indicadores de cultura","Plan de gestión del cambio","Cronograma de implementación a 12 meses"]'::jsonb, 1);
INSERT INTO public.academy_modulos (id, diplomado_id, nombre, objetivo, temas, taller, orden) VALUES ('04f06d62-2b19-4f3c-b9d8-973e6cc04b4a', '1f087b6a-3dd1-415b-ba30-b86c2382d65d', 'Fundamentos de la Visión Organizacional', 'Comprender el papel de la visión como elemento orientador de toda organización y su influencia en la cultura, el liderazgo y la toma de decisiones.', '["¿Qué es una visión?","Diferencia entre visión, misión y propósito","El origen de una visión","La visión como ventaja estratégica","Características de una visión inspiradora","La visión como eje organizacional","Cómo la visión orienta las decisiones","Visión y crecimiento","Visión compartida","Alineación institucional","¿La organización conoce su visión?","Síntomas de una visión débil","Evaluación del nivel de alineación","Barreras comunes","Casos de estudio"]'::jsonb, 'Diagnóstico de la visión actual de la iglesia. Producto: Informe de diagnóstico.', 1);
INSERT INTO public.academy_modulos (id, diplomado_id, nombre, objetivo, temas, taller, orden) VALUES ('c4028f35-95f6-4cda-8919-a26911f2d94e', '1f087b6a-3dd1-415b-ba30-b86c2382d65d', 'Identidad y ADN Institucional', 'Definir los elementos que conforman la identidad institucional y construir un ADN organizacional coherente.', '["¿Qué es identidad organizacional?","Historia institucional","Legado","Propósito","Vocación ministerial","Cultura","Valores","Principios","Creencias","Comportamientos","Misión","Visión","Valores","Propuesta de valor","Diferenciación"]'::jsonb, 'Construcción del ADN institucional. Producto: Documento de identidad institucional.', 2);
INSERT INTO public.academy_modulos (id, diplomado_id, nombre, objetivo, temas, taller, orden) VALUES ('a87c34a8-169a-40b8-8e1a-2422f953baf3', '1f087b6a-3dd1-415b-ba30-b86c2382d65d', 'Construcción de Cultura Organizacional', 'Diseñar una cultura organizacional que refleje la identidad y fortalezca el cumplimiento de la visión.', '["Concepto de cultura organizacional","Componentes","Niveles de cultura","Cultura visible e invisible","Cultura organizacional saludable","Construcción de valores","Vivencia de valores","Cultura del servicio","Cultura de excelencia","Cultura del Reino","Compromiso","Responsabilidad","Trabajo colaborativo","Innovación","Aprendizaje continuo"]'::jsonb, 'Mapa cultural de la iglesia. Producto: Diagnóstico cultural.', 3);
INSERT INTO public.academy_modulos (id, diplomado_id, nombre, objetivo, temas, taller, orden) VALUES ('70143bfa-10c0-4ebc-97e6-150d9dda1d8f', '1f087b6a-3dd1-415b-ba30-b86c2382d65d', 'Comunicación Estratégica de la Visión', 'Desarrollar estrategias para comunicar la visión de forma clara, consistente e inspiradora.', '["Comunicación interna y externa","Storytelling","Narrativa institucional","Mensaje central","Reuniones","Predicación","Redes sociales","Diseño gráfico","Material institucional","Comunicación de líderes","Comunicación entre ministerios","Retroalimentación","Escucha activa","Gestión de la información"]'::jsonb, 'Diseño del Plan de Comunicación de la Visión. Producto: Manual de comunicación.', 4);
