INSERT INTO public.academy_modulos (id, diplomado_id, nombre, objetivo, temas, taller, orden) VALUES ('d6cc7bdc-fa9c-41ba-a7de-ddaa8ec57272', '1f087b6a-3dd1-415b-ba30-b86c2382d65d', 'Gobierno Organizacional', 'Diseñar una estructura organizacional alineada con la visión institucional.', '["Gobierno organizacional","Organigrama","Niveles de autoridad","Manual de funciones","Responsabilidades","Toma de decisiones","Comités","Políticas","Rendición de cuentas","Buen gobierno"]'::jsonb, 'Diseño del organigrama institucional. Producto: Modelo de gobierno.', 7);
