INSERT INTO public.academy_diplomados (id, facultad_id, numero, titulo, subtitulo, duracion, modalidad, nivel, objetivo_general, dirigido_a, competencias, proyecto_final, orden) VALUES ('043b4f59-0998-4e2b-a470-01260306ff86', '83bfcf89-6ba5-41bf-9ab8-7cd3bcfb0e3a', 'IV', 'Discipulado Estratégico', 'Diseñando iglesias que hacen discípulos, forman líderes y transforman comunidades', '40 Horas', 'Presencial • Virtual • Híbrida', 'Diplomado Profesional', 'Capacitar a líderes e iglesias para diseñar, implementar y evaluar un sistema integral de discipulado que permita evangelizar, integrar, formar, desarrollar y enviar discípulos comprometidos con la misión de la iglesia.', '["Pastores","Líderes de discipulado","Coordinadores de consolidación","Líderes de grupos pequeños","Supervisores","Mentores","Maestros bíblicos"]'::jsonb, '["Diseñar un sistema integral de discipulado","Fortalecer la consolidación de nuevos creyentes","Implementar rutas de crecimiento espiritual","Formar mentores y discipuladores","Desarrollar procesos de seguimiento","Crear indicadores de discipulado","Multiplicar líderes y grupos pequeños","Evaluar el impacto del discipulado"]'::jsonb, '["Diagnóstico del discipulado actual","Ruta de crecimiento espiritual","Plan de consolidación","Programa de mentoría","Escuela de desarrollo de líderes","Modelo de grupos pequeños","Sistema de seguimiento","Indicadores de crecimiento","Plan anual de implementación","Estrategia de mejora continua"]'::jsonb, 2);
