INSERT INTO public.academy_modulos (id, diplomado_id, nombre, objetivo, temas, taller, orden) VALUES ('b23a65a8-a848-46da-a137-4b2fdec38a93', '043b4f59-0998-4e2b-a470-01260306ff86', 'Evangelismo y Primer Contacto', 'Diseñar estrategias para alcanzar personas y facilitar su integración.', '["Cultura evangelística","Evangelismo relacional, comunitario y digital","Eventos evangelísticos","Grupos pequeños como herramienta evangelística","Primer contacto con nuevos asistentes","Hospitalidad","Registro y seguimiento inicial","Integración a la comunidad"]'::jsonb, 'Diseño del proceso de primer contacto.', 2);
